EXPECTED_SHA256 = "3fcc27728e4b79c8b4d00cf14aee2fd08f621b9ed29fc31c970a6d9e6fce08a5"


def main() -> None:
    data = base64.b64decode(PNG_B64)
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        raise SystemExit("embedded data is not a PNG")
    os.makedirs("/output", exist_ok=True)
    with open("/output/entry.png", "wb") as f:
        f.write(data)
    digest = hashlib.sha256(data).hexdigest()
    print("wrote /output/entry.png (%d bytes, sha256=%s)" % (len(data), digest))
    if digest != EXPECTED_SHA256:
        raise SystemExit("sha256 mismatch: embedded image changed")


if __name__ == "__main__":
    main()
